create extension if not exists pgcrypto;
create table if not exists public.portal_users(id uuid primary key references auth.users(id) on delete cascade,email text not null,is_admin boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.driver_submissions(id uuid primary key default gen_random_uuid(),driver_key text not null,driver_name text not null,submitter_id uuid not null references auth.users(id),submitter_email text not null,status text not null default 'pending_review' check(status in('pending_review','approved','rejected')),payload jsonb not null default '{}',review_note text,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.submission_assets(id uuid primary key default gen_random_uuid(),submission_id uuid not null references public.driver_submissions(id) on delete cascade,category text not null check(category in('headshot','car','evidence','media')),object_path text not null unique,original_name text not null,content_type text not null,byte_size bigint not null check(byte_size between 1 and 10485760),created_at timestamptz not null default now());
create index if not exists submissions_owner_created on public.driver_submissions(submitter_id,created_at desc);create index if not exists submissions_status_created on public.driver_submissions(status,created_at desc);
create or replace function public.sync_portal_user()returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.portal_users(id,email)values(new.id,coalesce(new.email,''))on conflict(id)do update set email=excluded.email;return new;end$$;
drop trigger if exists auth_user_to_portal on auth.users;create trigger auth_user_to_portal after insert or update of email on auth.users for each row execute function public.sync_portal_user();
alter table public.portal_users enable row level security;alter table public.driver_submissions enable row level security;alter table public.submission_assets enable row level security;
create policy "own portal identity" on public.portal_users for select using(id=auth.uid());
create policy "submit own profile" on public.driver_submissions for insert with check(submitter_id=auth.uid() and submitter_email=coalesce(auth.jwt()->>'email',''));
create policy "read own or admin submissions" on public.driver_submissions for select using(submitter_id=auth.uid() or exists(select 1 from public.portal_users u where u.id=auth.uid() and u.is_admin));
create policy "insert own submission assets" on public.submission_assets for insert with check(exists(select 1 from public.driver_submissions s where s.id=submission_id and s.submitter_id=auth.uid()));
create policy "read own or admin assets" on public.submission_assets for select using(exists(select 1 from public.driver_submissions s where s.id=submission_id and(s.submitter_id=auth.uid() or exists(select 1 from public.portal_users u where u.id=auth.uid() and u.is_admin))));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('driver-submissions','driver-submissions',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "upload own driver files" on storage.objects for insert to authenticated with check(bucket_id='driver-submissions' and(storage.foldername(name))[1]=auth.uid()::text);
create policy "read own driver files" on storage.objects for select to authenticated using(bucket_id='driver-submissions' and((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.portal_users u where u.id=auth.uid() and u.is_admin)));
create or replace function public.review_driver_submission(submission_id uuid,new_status text,reviewer_note text default null)returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from portal_users where id=auth.uid() and is_admin)then raise exception 'Administrator access required';end if;if new_status not in('approved','rejected')then raise exception 'Invalid review status';end if;update driver_submissions set status=new_status,review_note=nullif(reviewer_note,''),reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now()where id=submission_id;if not found then raise exception 'Submission not found';end if;end$$;revoke all on function public.review_driver_submission(uuid,text,text)from public;grant execute on function public.review_driver_submission(uuid,text,text)to authenticated;
